//partly based on the Meshless Voronoi on the GPU
//https://inria.hal.science/hal-01927559v1/file/voroGPU.pdf

#define MAX_SITES 100
#define MAX_STEPS 50
#define MIN_DIST 0.002
#define MAX_DIST 50.0
#define EPSILON 0.002
#define CELL_TRANSPARENCY 0.01
#define AUTO_ROTATE_SPEED 0.4
#define CUBE_SIZE 1.0
#define GRID_SIZE 4

struct Site {
    vec3 pos;
    float weight;
};

// Grid structure
#define MAX_SITES_PER_CELL 20

struct GridCell {
    int count;
    int sites[MAX_SITES_PER_CELL];
};

Site sites[MAX_SITES];
GridCell grid[GRID_SIZE * GRID_SIZE * GRID_SIZE];

// Precomputed Grid Size values
const int GRID_SIZE_SQUARED = GRID_SIZE * GRID_SIZE;
const int GRID_SIZE_CUBED = GRID_SIZE * GRID_SIZE * GRID_SIZE;

// Precomputed CUBE_SIZE constants
const vec3 CUBE_SIZE_VEC = vec3(CUBE_SIZE);
const vec3 NEG_CUBE_SIZE_VEC = vec3(-CUBE_SIZE);


vec3 hash33(vec3 p3) {
    p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz + 33.33);
    return -1.0 + 2.0 * fract(vec3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
}

vec3 noise3D(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    vec3 u = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(mix(hash33(i + vec3(0,0,0)), hash33(i + vec3(1,0,0)), u.x),
            mix(hash33(i + vec3(0,1,0)), hash33(i + vec3(1,1,0)), u.x), u.y),
        mix(mix(hash33(i + vec3(0,0,1)), hash33(i + vec3(1,0,1)), u.x),
            mix(hash33(i + vec3(0,1,1)), hash33(i + vec3(1,1,1)), u.x), u.y), u.z);
}

ivec3 posToGrid(vec3 pos) {
    vec3 normalized = (pos / CUBE_SIZE + 1.0) * 0.5;
    return clamp(ivec3(normalized * float(GRID_SIZE)), ivec3(0), ivec3(GRID_SIZE - 1));
}

int gridIndex(ivec3 pos) {
    return pos.x + GRID_SIZE * (pos.y + GRID_SIZE * pos.z);
}

void initGrid() {
    for(int i = 0; i < GRID_SIZE_CUBED; i++) {
        grid[i].count = 0;
    }

    for(int i = 0; i < MAX_SITES; i++) {
        ivec3 cell = posToGrid(sites[i].pos);
        int idx = gridIndex(cell);
        if(grid[idx].count < MAX_SITES_PER_CELL) {
            grid[idx].sites[grid[idx].count] = i;
            grid[idx].count++;
        }
    }
}

void initSites() {
    for(int i = 0; i < MAX_SITES; i++) {
        vec3 basePos = vec3(
            hash33(vec3(float(i), 0.0, 0.0)).x,
            hash33(vec3(0.0, float(i), 0.0)).y,
            hash33(vec3(0.0, 0.0, float(i))).z
        );

        vec3 movement = noise3D(basePos + vec3(iTime * 0.2));
        vec3 pos = basePos + movement * 0.2;
        pos = clamp(pos, vec3(-0.8), vec3(0.8)) * CUBE_SIZE;

        sites[i].pos = pos;
        sites[i].weight = 0.0;
    }

    initGrid();
}

void getCellInfo(vec3 p, out float minDist, out int cellId, out float secondMinDist) {
    minDist = MAX_DIST;
    secondMinDist = MAX_DIST;
    cellId = -1;

    ivec3 gridPos = posToGrid(p);

    for(int dx = -1; dx <= 1; dx++) {
        for(int dy = -1; dy <= 1; dy++) {
            for(int dz = -1; dz <= 1; dz++) {
                ivec3 cell = gridPos + ivec3(dx, dy, dz);
                if(any(lessThan(cell, ivec3(0))) || any(greaterThanEqual(cell, ivec3(GRID_SIZE)))) 
                    continue;

                int idx = gridIndex(cell);
                for(int i = 0; i < grid[idx].count; i++) {
                    int siteId = grid[idx].sites[i];
                    float d = length(p - sites[siteId].pos);

                    if(d < minDist) {
                        secondMinDist = minDist;
                        minDist = d;
                        cellId = siteId;
                    } else if(d < secondMinDist) {
                        secondMinDist = d;
                    }
                }
            }
        }
    }
}

vec2 cubeIntersection(vec3 ro, vec3 rd) {
    vec3 inv_dir = 1.0 / rd;
    vec3 tmin_temp = (NEG_CUBE_SIZE_VEC - ro) * inv_dir;
    vec3 tmax_temp = (CUBE_SIZE_VEC - ro) * inv_dir;
    vec3 tmin = min(tmin_temp, tmax_temp);
    vec3 tmax = max(tmin_temp, tmax_temp);
    float t0 = max(max(tmin.x, tmin.y), tmin.z);
    float t1 = min(min(tmax.x, tmax.y), tmax.z);
    return vec2(t0, t1);
}

vec4 getCellColor(int id, float alpha) {
    float hue = mix(0.525, 0.35, fract(float(id) * 0.12345));
    vec3 color =  0.5 + 0.5 * cos(2.0 * 3.14159 * (hue + vec3(0.0, 0.33, 0.67)));
    return vec4(color, alpha);
}

float drawCentroid(vec3 p, vec3 centerPos) {
    float radius = 0.015;
    return length(p - centerPos) - radius;
}

vec3 getCameraPosition(float zoom) {
    float autoAngle = iTime * AUTO_ROTATE_SPEED;
    float isInteracting = iMouse.z > 0.0 ? 1.0 : 0.0;
    vec2 mousePos = iMouse.xy / iResolution.xy;
    float angle = mix(autoAngle, mousePos.x * 6.28318, isInteracting);

    return vec3(
        zoom * sin(angle),
        zoom * 0.5,
        zoom * cos(angle)
    );
}

// Function to calculate the normal of the cube at a given point
vec3 calculateCubeNormal(vec3 p) {
    vec3 absP = abs(p);
    if (absP.x > absP.y && absP.x > absP.z) {
        return vec3(sign(p.x), 0.0, 0.0);
    } else if (absP.y > absP.z) {
        return vec3(0.0, sign(p.y), 0.0);
    } else {
        return vec3(0.0, 0.0, sign(p.z));
    }
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    initSites();

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float zoom = 3.0 - (iMouse.y / iResolution.y) * 1.5;
    zoom = clamp(zoom, 1.5, 3.0);

    vec3 ro = getCameraPosition(zoom);
    vec3 lookAt = vec3(0.0);
    vec3 forward = normalize(lookAt - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = cross(forward, right);
    vec3 rd = normalize(mat3(right, up, forward) * vec3(uv, 1.0));

    vec2 cube_t = cubeIntersection(ro, rd);

    // Gradient background calculation (corrected)
    float gradientFactor = clamp(1.0 - (uv.y * 0.5 + 0.5), 0.0, 1.0);
    vec3 lightGray = vec3(0.9);
    vec3 mediumGray = vec3(0.005);
    vec3 backgroundColor = mix(lightGray, mediumGray, gradientFactor);
    vec4 finalColor = vec4(backgroundColor, 1.0);

      // External Glow (Corrected)
    float externalDistToSurface = MAX_DIST;

    if(cube_t.x > 0.0) { // Only compute glow if cube is intersected

      // Estimate point on the cube's surface
      float t_surface = cube_t.x; // Using the near intersection
      vec3 surface_point = ro + rd * t_surface; 

      // Find the surface normal of the cube.
       vec3 normal = calculateCubeNormal(surface_point);

       vec3 pos_external = surface_point + normal * 0.2; // Move the calculation point out of the cube

        for (int j = 0; j < MAX_SITES; j++) {
             externalDistToSurface = min(externalDistToSurface, length(pos_external - sites[j].pos));
        }

        float glowAmount = smoothstep(0.8, 0.0, externalDistToSurface);
          finalColor.rgb = mix(finalColor.rgb, vec3(1.0),  glowAmount * 1.2);
      }

    // Internal Shine
    if(cube_t.x < cube_t.y && cube_t.y > 0.0) {
        float t = max(0.0, cube_t.x);
        vec3 pos = ro + rd * t;

        float internalDistToSurface = MAX_DIST;
           for(int j = 0; j < MAX_SITES; j++) {
             internalDistToSurface = min(internalDistToSurface, length(pos - sites[j].pos));
           }
        float internalShineAmount = smoothstep(0.2, 0.0, internalDistToSurface); // Inverted smoothstep

         finalColor.rgb = mix(finalColor.rgb, vec3(1.0),  (1.0-internalShineAmount) * 0.2);


        vec4 acc = vec4(0.0);
        for(int i = 0; i < MAX_STEPS && t < cube_t.y; i++) {
            if(acc.a >= 0.98) break;

            float minCentroidDist = MAX_DIST;
            for(int j = 0; j < MAX_SITES; j++) {
                float centroidDist = drawCentroid(pos, sites[j].pos);
                minCentroidDist = min(minCentroidDist, centroidDist);
            }

            if(minCentroidDist < EPSILON) {
                acc = mix(acc, vec4(1.0), 0.9);
                break;
            }

            int cellId;
            float minDist, secondMinDist;
            getCellInfo(pos, minDist, cellId, secondMinDist);

            float boundaryDist = abs(secondMinDist - minDist);
            float stepSize = boundaryDist > 0.1 ? boundaryDist * 0.5 : 0.02;

            if(boundaryDist < 0.02) {
                vec4 cellColor = getCellColor(cellId, CELL_TRANSPARENCY);
                float alpha = (1.0 - acc.a) * cellColor.a;
                acc += vec4(cellColor.rgb * alpha, alpha);
            }

            t += stepSize;
            pos = ro + rd * t;
        }

        if(acc.a > 0.0) {
            finalColor = vec4(acc.rgb / acc.a, acc.a);
        }
    }

    fragColor = finalColor;
}
